<?php
namespace Tests;
use App\Services\{SalonStore,Tenant,Settings};
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{DB,Cache,Artisan,Hash};
final class DiscoveryTest extends TestCase
{
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();if(config('database.default')!=='sqlite'&&!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Külön tesztadatbázis szükséges.');Artisan::call('migrate',['--force'=>true]);DB::table('salon_state')->delete();DB::table('providers')->delete();Cache::flush();$s=SalonStore::initial();$s['profile']=['city'=>'Budapest','address'=>'Minta utca 1.','categories'=>['hair']];DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode($s)]);$this->withSession(['_token'=>str_repeat('d',40)])->withHeader('X-CSRF-TOKEN',str_repeat('d',40));}
 private function registration(array $v=[]):array{return array_replace(['name'=>'Új vállalkozás','email'=>'owner@example.com','password'=>'Long-test-password-123','password_confirmation'=>'Long-test-password-123','city'=>'Győr','category'=>'fitness'],$v);}
 public function test_filters_can_be_combined_and_facets_are_public_only():void{$s=SalonStore::initial();$s['settings']['name']='Másik hely';$s['profile']=['city'=>'Győr','categories'=>['fitness']];$s['clients']=[['id'=>'private','name'=>'Private Guest']];DB::table('providers')->insert(['id'=>2,'name'=>'Másik hely','email'=>'private@example.com','password_hash'=>'private-hash','active'=>true,'trial_started_at'=>now(),'trial_ends_at'=>now()->addMonths(2),'created_at'=>now(),'updated_at'=>now()]);DB::table('salon_state')->insert(['id'=>2,'data'=>json_encode($s)]);$r=$this->getJson('/api/providers?category=fitness&city=gyor&q=masik')->assertOk()->assertJsonPath('total',1)->assertJsonPath('items.0.id',2)->assertJsonPath('items.0.city','Győr');$this->assertStringNotContainsString('private@example.com',$r->getContent());$this->assertStringNotContainsString('Private Guest',$r->getContent());$this->assertSame(['Budapest','Győr'],$r->json('cities'));$this->getJson('/api/providers?category=hair&city=gyor')->assertJsonPath('total',0);$this->getJson('/api/providers?category=invalid')->assertUnprocessable();}
 public function test_profile_city_categories_and_uploaded_media_are_saved_and_invalidate_cache():void{$this->getJson('/api/providers?city=Győr')->assertJsonPath('total',0);$this->withSession(['admin'=>true,'provider_id'=>1]);$this->putJson('/api/profile',['city'=>'Győr','zip'=>'9000','categories'=>['fitness'],'logo'=>'/media/12345678-1234-1234-1234-123456789abc','cover'=>'/media/22345678-1234-1234-1234-123456789abc','photos'=>[]])->assertOk();$this->getJson('/api/providers?city=gyor&category=fitness')->assertJsonPath('total',1)->assertJsonPath('items.0.logo','/media/12345678-1234-1234-1234-123456789abc');$this->putJson('/api/profile',['categories'=>['bad']])->assertUnprocessable();$this->putJson('/api/profile',['cover'=>'javascript:alert(1)'])->assertUnprocessable();}
 public function test_registration_creates_isolated_empty_solo_account_without_platform_rights():void{$r=$this->postJson('/api/provider-register',$this->registration())->assertCreated()->assertJsonPath('id',2)->assertSessionHas('admin',true)->assertSessionHas('provider_id',2);$this->assertFalse((bool)session('platform_admin'));$row=DB::table('providers')->find(2);$this->assertTrue(Hash::check('Long-test-password-123',$row->password_hash));$this->assertStringNotContainsString('Long-test-password',$r->getContent());$s=json_decode(DB::table('salon_state')->where('id',2)->value('data'),true);$this->assertSame([],$s['services']);$this->assertSame([],$s['clients']);$this->assertSame('solo',$s['settings']['businessMode']);$this->assertSame('Győr',$s['profile']['city']);$this->assertSame(1,$s['subscription']['calendarLimit']);$this->getJson('/api/platform/providers?provider=2')->assertUnauthorized();$this->getJson('/api/state?provider=1')->assertForbidden();$this->getJson('/api/state?provider=2')->assertOk();$this->assertSame('Harmónia Szalon',json_decode(DB::table('salon_state')->where('id',1)->value('data'),true)['settings']['name']);}
 public function test_registration_validation_duplicate_email_and_email_login():void{$this->postJson('/api/provider-register',$this->registration(['password_confirmation'=>'different']))->assertUnprocessable();$this->postJson('/api/provider-register',$this->registration())->assertCreated();$this->withSession(['admin'=>false,'provider_id'=>1]);$this->postJson('/api/provider-register',$this->registration(['email'=>'OWNER@EXAMPLE.COM']))->assertUnprocessable();$this->postJson('/api/provider-login',['email'=>'owner@example.com','password'=>'wrong'])->assertUnauthorized();$this->postJson('/api/provider-login',['email'=>'OWNER@example.com','password'=>'Long-test-password-123'])->assertOk()->assertJsonPath('id',2)->assertSessionHas('provider_id',2);$this->getJson('/api/platform/providers?provider=2')->assertUnauthorized();}
 public function test_signed_in_provider_cannot_accidentally_create_another_account():void{$this->withSession(['admin'=>true,'provider_id'=>1]);$this->postJson('/api/provider-register',$this->registration())->assertStatus(409);$this->assertSame(0,DB::table('providers')->count());}
}
